  const shortLabel=n=>language==='zh'?(n?.short_zh||n?.short_en||titleOf(n)):(n?.short_en||titleOf(n));
  const shortQuestion=q=>shortLabel(learningBlueprint?.question_labels?.[q.id]||{short_en:'Question',short_zh:'问题'});
  const shortYear=yr=>shortLabel(learningBlueprint?.year_labels?.[yr]||{short_en:'Research',short_zh:'研究'});
  const branchQuestions=(branch,questions=eligibleQuestions())=>questions.filter(q=>(branch.question_ids||[]).includes(q.id));
  const keywordById=id=>learningBlueprint.keywords.find(k=>k.id===id);
  const keywordQuestions=(keyword,questions=eligibleQuestions(),related=false)=>questions.filter(q=>(related?keyword.related_question_ids:keyword.primary_question_ids).includes(q.id));
  const keywordMatches=(keyword,questions=eligibleQuestions())=>questions.some(q=>[...keyword.primary_question_ids,...keyword.related_question_ids].includes(q.id));
  const keywordsForBranch=(branch,questions=eligibleQuestions())=>learningBlueprint.keywords.filter(k=>branch.keyword_ids.includes(k.id)&&keywordMatches(k,questions));
  const relationTypes={
    contains:{label:'Contains a record · navigation, not causality',note:'A year contains dated records. Core, branch and keyword membership is our learning navigation, not evidence that one study caused another.'},
    career_transition:{label:'Documented author-described transition',note:'Personal accounts support only the stated career or research-emphasis transition. Publication dates do not reconstruct a new field every year.'},
    project_origin:{label:'Documented team / project origin',note:'Official workshop records support a project or review-team origin, not a first meeting, universal motive or result.'},
    shared_method_boundary_theme:{label:'Method / boundary / data bridge · non-causal',note:'The sources support the stated method family, boundary extension, framework update or data bridge. Direction does not mean confirmed inspiration or career causality.'},
    parallel_branch:{label:'Parallel thematic connection · our synthesis',note:'The papers support both endpoints. Their thematic comparison is our editorial reading, with no causal claim.'},
    funded_question:{label:'Funded new question / planned method',note:'The AI record is a funded research plan. Its shared-location, power and health connections are editorial, and its planned method is not a completed tool or finding.'}
  };
  let data,view='topics',topic='all',year='all',search='',selected={kind:'question',id:'q-trade-security'},expandedTopics=new Set(),expandedYears=new Set(),includeMethods=false;
  let ratings={},storageAvailable=true,zoom,transform,layout,svg,world,viewport={width:1400,height:780};
  const narrow=()=>matchMedia('(max-width:800px)').matches;
  try{const old=JSON.parse(localStorage.getItem(storageKey)||'{}');if(old&&typeof old==='object'&&!Array.isArray(old))ratings=Object.fromEntries(Object.entries(old).filter(([,v])=>Object.hasOwn(interestLabels,v)));}catch{storageAvailable=false;}
  const rating=id=>ratings[id]||'unrated';
  const allEvidenceNodes=()=>[...data.questions,...data.methods,...data.contexts,...data.clusters,...(learningBlueprint?[learningBlueprint.core,...learningBlueprint.branches,...learningBlueprint.keywords]:[])];
  const questionById=id=>data.questions.find(q=>q.id===id);
  const nodeById=id=>allEvidenceNodes().find(n=>n.id===id);
  const titleOf=n=>language==='zh'?(n?.question_zh||n?.title_zh||n?.question_en||n?.title||n?.id||''):(n?.question_en||n?.title||n?.title_en||n?.id||'');
  const selectedId=()=>selected.id;
  const mapSelectedId=()=>selected.kind==='question'?(learningBlueprint.keywords.find(k=>k.primary_question_ids.includes(selected.id))?.id||selected.id):selected.id;
  function eligibleQuestions(){return data.questions.filter(q=>(topic==='all'||q.cluster_ids.includes(topic))&&(year==='all'||q.year===Number(year))&&(!search||[q.question_en,q.question_zh,q.paper_title,q.year].join(' ').toLowerCase().includes(search)));}
  function sourceHTML(ids){const lookup=new Map(data.sources.map(s=>[s.id,s]));return [...new Set(ids||[])].map(id=>lookup.get(id)).filter(Boolean).map(s=>`<div><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)}</a><small>${esc(s.date)} · ${esc(s.kind)}</small>${s.note?`<small>${esc(s.note)}</small>`:''}</div>`).join('');}
  function filmURL(q){return Number.isInteger(q.film_year)?`research.html?year=${q.film_year}${Number.isInteger(q.film_card)?`&card=${q.film_card}`:''}#research-film`:null;}
  function interestEditor(id,label){return `<fieldset class="km-interest-editor"><legend>${language==='zh'?'我的兴趣 · ':'My interest in '}${esc(label)}</legend><div class="km-interest-options">${Object.entries(interestLabels).map(([level,name])=>`<label data-interest="${level}"><input type="radio" name="km-interest" value="${level}" data-rate-id="${esc(id)}" ${rating(id)===level?'checked':''}>${esc(interestText(level))}</label>`).join('')}</div><p>${language==='zh'?'未评级表示没有输入偏好。选择只保存在本浏览器中，不改变其他节点。':'Unrated means no preference entered. Ratings stay in this browser and do not change other nodes.'}</p></fieldset>`;}
  function saveRating(id,value){if(!Object.hasOwn(interestLabels,value))return;if(value==='unrated')delete ratings[id];else ratings[id]=value;try{localStorage.setItem(storageKey,JSON.stringify(ratings));storageAvailable=true;}catch{storageAvailable=false;}$('km-storage-status').textContent=storageAvailable?`Saved locally: ${interestText(value)}.`:'Rating changed in this view; local browser storage is unavailable.';renderMap();showDetail();}
