  function textLines(text,maxChars,maxLines){const words=String(text).split(/\s+/),lines=[];let line='';for(const word of words){if(line&&line.length+word.length+1>maxChars){lines.push(line);line=word;}else line+=(line?' ':'')+word;}if(line)lines.push(line);if(lines.length>maxLines){const kept=lines.slice(0,maxLines);kept[maxLines-1]=kept[maxLines-1].slice(0,maxChars-1)+'…';return kept;}return lines;}
