      const visibleKeywordIds=new Set(years.filter(yr=>expandedYears.has(yr)).flatMap(yr=>learningBlueprint.year_keywords[yr]||[])),children=learningBlueprint.keywords.filter(k=>visibleKeywordIds.has(k.id)&&keywordMatches(k,qs));
