    group.append('rect').attr('width',n=>n.w).attr('height',n=>n.h).attr('rx',n=>n.kind==='concept-core'?28:n.kind==='concept'?18:8);
    group.filter(n=>n.kind!=='root').append('rect').attr('class','km-interest-bar').attr('x',0).attr('y',0).attr('width',5).attr('height',n=>n.h);
    group.each(function(n){const g=d3.select(this);if(n.compact){const core=n.kind==='concept-core',maxChars=language==='zh'?12:core?22:n.kind==='concept'?17:27,lines=textLines(n.title,maxChars,2),x=core?n.w/2:20,start=core?43:31,title=g.append('text').attr('class','km-node-title').attr('x',x).attr('y',start).attr('text-anchor',core?'middle':'start');lines.forEach((line,i)=>title.append('tspan').attr('x',x).attr('dy',i?(core?35:25):0).text(line));g.append('text').attr('class','km-compact-meta').attr('x',x).attr('y',n.h-14).attr('text-anchor',core?'middle':'start').text(n.meta);if(n.expandable)g.append('text').attr('class','km-expand-glyph').attr('x',n.w-24).attr('y',29).text(n.open?'−':'+');g.append('title').text(n.fullTitle||n.title);return;}const maxChars=n.kind==='question'?Math.floor((n.w-40)/10):30,lines=textLines(n.title,maxChars,n.kind==='question'?3:2),start=29;const t=g.append('text').attr('class','km-node-title').attr('x',17).attr('y',start);lines.forEach((line,i)=>t.append('tspan').attr('x',17).attr('dy',i?(n.kind==='question'?19:22):0).text(line));g.append('text').attr('class','km-node-meta').attr('x',n.kind==='year'?96:17).attr('y',n.kind==='year'?29:n.h-28).text(n.meta);if(n.kind!=='root')g.append('text').attr('class','km-node-interest').attr('x',17).attr('y',n.h-10).text(`Interest: ${interestText(rating(n.interestId||n.id))}`);if(n.expandable)g.append('text').attr('class','km-expand-glyph').attr('x',n.w-28).attr('y',28).text(n.open?'−':'+');g.append('title').text(n.title);});
    $('km-counts').textContent=`${layout.questionCount} matching questions · ${data.clusters.length} themes · 19 years / 26 exact film views`;
    $('km-map-note').textContent=view==='tree'?(language==='zh'?'年份包含来源记录，关键词可跨年返回。这里的分支不是学术因果链，具体论文和动画视图在详情中保留。':'Years contain source records, and keywords can return across years. These branches are not a causal research chain. Exact papers and film views remain in the inspector.'):(language==='zh'?'中心、分支与关键词是我们的学习归纳，不是作者原话或统一工作流。层级线仅表示阅读入口；有证据类型的学术关系在所选记录中单独显示。':'Core, branches and keywords are our learning synthesis, not an author quotation or universal workflow. Hierarchy lines mean reading paths; evidence-typed scholarly relationships are inspected separately.');
